import type {
  AccountingDossier,
  BorrowVsSellPreview,
  DeductibleExpenseInput,
  DeductibleExpensePreview,
  Jurisdiction,
  SelectedLotDisposal,
  TaxRegime,
  TlhOpportunity,
} from "@taxrail/shared";

export const DEFAULT_PTAX_USD_BRL = 5.8;

export const TAXRAIL_ACCOUNTING_DISCLAIMER =
  "Software-only accounting and tax simulation generated by TaxRail. Informational output only — does not constitute legal, tax, or accounting advice. Final tax filing, IRS Form 8949 / Schedule C / Form 1120 reporting, and Brazilian DeCripto / SPED / Lei 14.754 submissions require review and sign-off by a licensed CPA (US) or Contador (BR).";

const FORM_8949_CSV_HEADER =
  "Description of Property,Date Acquired,Date Sold,Proceeds,Cost Basis,Code,Adjustment,Gain or Loss,Term";

function round2(value: number): number {
  return Math.round((value + Number.EPSILON) * 100) / 100;
}

function formatIsoDate(ms: number): string {
  return new Date(ms).toISOString().slice(0, 10);
}

function escapeCsvCell(value: string | number): string {
  const str = String(value);
  if (/[",\n\r]/.test(str)) {
    return `"${str.replace(/"/g, '""')}"`;
  }
  return str;
}

function buildCsv(headers: string[], rows: Array<Array<string | number>>): string {
  const lines = [
    headers.map(escapeCsvCell).join(","),
    ...rows.map((row) => row.map(escapeCsvCell).join(",")),
  ];
  return lines.join("\n");
}

function sumBy<T>(items: T[], selector: (item: T) => number): number {
  let total = 0;
  for (const item of items) {
    total += selector(item);
  }
  return total;
}

/**
 * Builds an accounting dossier for crypto lot disposals and tax-loss harvesting:
 * - US: IRS Form 8949 structured records + CSV export
 * - BR: Lei 14.754 / DeCripto dossier with USD & BRL (PTAX reference) totals
 */
export function buildCryptoAccountingDossier(params: {
  jurisdiction: Jurisdiction;
  regime: TaxRegime;
  selectedLots: SelectedLotDisposal[];
  tlhOpportunities: TlhOpportunity[];
  taxSavedUsd: number;
}): AccountingDossier {
  const { jurisdiction, regime, selectedLots, tlhOpportunities, taxSavedUsd } =
    params;

  const nowMs = Date.now();
  const generatedAt = new Date(nowMs).toISOString();
  const dateSold = formatIsoDate(nowMs);

  const totalProceedsUsd = round2(sumBy(selectedLots, (l) => l.proceedsUsd));
  const totalCostBasisUsd = round2(
    sumBy(selectedLots, (l) => l.costBasisTotalUsd)
  );
  const totalGainOrLossUsd = round2(
    sumBy(selectedLots, (l) => l.gainOrLossUsd)
  );
  const estimatedTaxUsd = round2(
    sumBy(selectedLots, (l) => l.estimatedTaxUsd)
  );
  const totalTlhTaxShieldUsd = round2(
    sumBy(tlhOpportunities, (t) => t.estimatedTaxShieldUsd)
  );

  if (jurisdiction === "US") {
    const shortTermGainOrLossUsd = round2(
      sumBy(
        selectedLots.filter((l) => l.term === "SHORT_TERM"),
        (l) => l.gainOrLossUsd
      )
    );
    const longTermGainOrLossUsd = round2(
      sumBy(
        selectedLots.filter((l) => l.term === "LONG_TERM"),
        (l) => l.gainOrLossUsd
      )
    );

    const records = selectedLots.map((lot) => {
      const acquiredMs = nowMs - Math.max(0, lot.holdingDays) * 86_400_000;
      const dateAcquired = formatIsoDate(acquiredMs);
      const descriptionOfProperty = `${lot.quantityToSell} ${lot.asset}`;
      const term = lot.term === "LONG_TERM" ? "LONG_TERM" : "SHORT_TERM";
      const form8949Part =
        term === "LONG_TERM" ? "Part II (Long-Term)" : "Part I (Short-Term)";

      return {
        lotId: lot.lotId,
        asset: lot.asset,
        quantity: lot.quantityToSell,
        descriptionOfProperty,
        dateAcquired,
        dateSold,
        proceedsUsd: round2(lot.proceedsUsd),
        costBasisUsd: round2(lot.costBasisTotalUsd),
        code: "",
        adjustmentUsd: 0,
        gainOrLossUsd: round2(lot.gainOrLossUsd),
        term,
        form8949Part,
        holdingDays: lot.holdingDays,
        effectiveTaxRate: lot.effectiveTaxRate,
        estimatedTaxUsd: round2(lot.estimatedTaxUsd),
      };
    });

    const csvRows = records.map((r) => [
      r.descriptionOfProperty,
      r.dateAcquired,
      r.dateSold,
      r.proceedsUsd.toFixed(2),
      r.costBasisUsd.toFixed(2),
      r.code,
      r.adjustmentUsd.toFixed(2),
      r.gainOrLossUsd.toFixed(2),
      r.term,
    ]);

    const csvExport = [
      FORM_8949_CSV_HEADER,
      ...csvRows.map((row) => row.map(escapeCsvCell).join(",")),
    ].join("\n");

    return {
      format: "IRS_FORM_8949",
      generatedAt,
      summary: {
        jurisdiction,
        regime,
        reportingForm: "IRS Form 8949 / Schedule D",
        totalLotsDisposed: selectedLots.length,
        totalProceedsUsd,
        totalCostBasisUsd,
        totalGainOrLossUsd,
        shortTermGainOrLossUsd,
        longTermGainOrLossUsd,
        estimatedTaxUsd,
        taxSavedUsd: round2(taxSavedUsd),
        tlhOpportunitiesCount: tlhOpportunities.length,
        totalTlhTaxShieldUsd,
      },
      records,
      csvExport,
      disclaimer: TAXRAIL_ACCOUNTING_DISCLAIMER,
    };
  }

  const ptax = DEFAULT_PTAX_USD_BRL;
  const records = selectedLots.map((lot) => {
    const proceedsUsd = round2(lot.proceedsUsd);
    const costBasisUsd = round2(lot.costBasisTotalUsd);
    const gainOrLossUsd = round2(lot.gainOrLossUsd);
    const lotTaxUsd = round2(lot.estimatedTaxUsd);

    return {
      lotId: lot.lotId,
      asset: lot.asset,
      quantity: lot.quantityToSell,
      holdingDays: lot.holdingDays,
      dateSold,
      regimeTag: lot.term,
      deCriptoClassification: "ALIENACAO_CRIPTOATIVOS_EXTERIOR_OU_DEX",
      lei14754TaxRatePct: round2(lot.effectiveTaxRate * 100),
      ptaxReferenceRate: ptax,
      proceedsUsd,
      proceedsBrl: round2(proceedsUsd * ptax),
      costBasisUsd,
      costBasisBrl: round2(costBasisUsd * ptax),
      gainOrLossUsd,
      gainOrLossBrl: round2(gainOrLossUsd * ptax),
      estimatedTaxUsd: lotTaxUsd,
      estimatedTaxBrl: round2(lotTaxUsd * ptax),
    };
  });

  return {
    format: "BR_LEI_14754",
    generatedAt,
    summary: {
      jurisdiction,
      regime,
      reportingFramework: "Lei 14.754/2023 & IN RFB DeCripto",
      ptaxReferenceRate: ptax,
      ptaxSource: "BCB_PTAX_REFERENCE",
      totalLotsDisposed: selectedLots.length,
      totalProceedsUsd,
      totalProceedsBrl: round2(totalProceedsUsd * ptax),
      totalCostBasisUsd,
      totalCostBasisBrl: round2(totalCostBasisUsd * ptax),
      totalGainOrLossUsd,
      totalGainOrLossBrl: round2(totalGainOrLossUsd * ptax),
      estimatedTaxUsd,
      estimatedTaxBrl: round2(estimatedTaxUsd * ptax),
      taxSavedUsd: round2(taxSavedUsd),
      taxSavedBrl: round2(taxSavedUsd * ptax),
      tlhOpportunitiesCount: tlhOpportunities.length,
      totalTlhTaxShieldUsd,
      totalTlhTaxShieldBrl: round2(totalTlhTaxShieldUsd * ptax),
    },
    records,
    disclaimer: TAXRAIL_ACCOUNTING_DISCLAIMER,
  };
}

/**
 * Builds an accounting dossier for a Borrow-vs-Sell liquidity decision,
 * capturing non-realization collateralized loan treatment or optimized disposal fallback.
 */
export function buildBorrowAccountingDossier(params: {
  jurisdiction: Jurisdiction;
  regime: TaxRegime;
  preview: BorrowVsSellPreview;
}): AccountingDossier {
  const { jurisdiction, regime, preview } = params;
  const generatedAt = new Date().toISOString();
  const isBorrow = preview.recommendation === "BORROW_AAVE_V3";

  const format: AccountingDossier["format"] =
    jurisdiction === "US"
      ? "IRS_FORM_8949"
      : regime === "PJ_LUCRO_REAL"
        ? "BR_LUCRO_REAL_OMIE_SPED"
        : "BR_LEI_14754";

  const ptax = DEFAULT_PTAX_USD_BRL;
  const accountingTreatment = isBorrow
    ? "NON_TAXABLE_COLLATERALIZED_LOAN"
    : "TAXABLE_DISPOSAL_PREFERRED";

  const summary: Record<string, unknown> = {
    planId: preview.planId,
    jurisdiction,
    regime,
    recommendation: preview.recommendation,
    accountingTreatment,
    taxReference:
      jurisdiction === "US"
        ? isBorrow
          ? "IRC § 1001 Non-Realization (Collateralized DeFi Loan); IRC § 163 Business Interest Tracking"
          : "IRC § 1001 / IRS Form 8949 Tax-Optimized Disposal"
        : isBorrow
          ? "Operação de Crédito Colateralizada (Sem Alienação / Sem Ganho de Capital no Aporte)"
          : "Alienação Otimizada — Lei 14.754 / IRPJ",
    sellTaxCostUsd: round2(preview.sellTaxCostUsd),
    netBorrowCostUsd: round2(preview.netBorrowCostUsd),
    corporateInterestTaxShieldUsd: round2(preview.corporateInterestTaxShieldUsd),
    taxSavedUsd: round2(preview.taxSavedUsd),
    projectedLtvPct: round2(preview.projectedLtvPct),
    liquidationWarning: preview.liquidationWarning,
    ...(jurisdiction === "BR"
      ? {
          ptaxReferenceRate: ptax,
          sellTaxCostBrl: round2(preview.sellTaxCostUsd * ptax),
          netBorrowCostBrl: round2(preview.netBorrowCostUsd * ptax),
          taxSavedBrl: round2(preview.taxSavedUsd * ptax),
        }
      : {}),
  };

  const records: Array<Record<string, unknown>> = isBorrow
    ? [
        {
          entryType: "COLLATERAL_LOCK_MEMO",
          protocol: "aave_v3",
          taxableEvent: false,
          projectedLtvPct: round2(preview.projectedLtvPct),
          description:
            "Collateral supplied to Aave v3 pool; ownership retained, no taxable disposal realized.",
        },
        {
          entryType: "DEBT_LIABILITY_AND_INTEREST_SHIELD",
          protocol: "aave_v3",
          netBorrowCostUsd: round2(preview.netBorrowCostUsd),
          corporateInterestTaxShieldUsd: round2(
            preview.corporateInterestTaxShieldUsd
          ),
          taxSavedUsd: round2(preview.taxSavedUsd),
          ...(jurisdiction === "BR"
            ? {
                netBorrowCostBrl: round2(preview.netBorrowCostUsd * ptax),
                taxSavedBrl: round2(preview.taxSavedUsd * ptax),
              }
            : {}),
          description:
            "Variable-rate USDC borrow liability booked; interest tracked for corporate deductibility where eligible.",
        },
      ]
    : [
        {
          entryType: "SELL_OPTIMIZED_LOTS_RECOMMENDED",
          taxableEvent: true,
          sellTaxCostUsd: round2(preview.sellTaxCostUsd),
          netBorrowCostUsd: round2(preview.netBorrowCostUsd),
          description:
            "Tax-optimized lot disposal is more cost-effective than DeFi borrowing cost over the requested horizon.",
        },
      ];

  return {
    format,
    generatedAt,
    summary,
    records,
    disclaimer: TAXRAIL_ACCOUNTING_DISCLAIMER,
  };
}

/**
 * Builds an accounting dossier for deductible business expenses:
 * - US: QUICKBOOKS_EXPENSE (IRS Schedule C / Corporate IRC § 162 deduction)
 * - BR: BR_LUCRO_REAL_OMIE_SPED (IRPJ/CSLL 34%, PIS/COFINS 9.25%, IBS/CBS readiness tags)
 */
export function buildExpenseAccountingDossier(params: {
  input: DeductibleExpenseInput;
  preview: DeductibleExpensePreview;
}): AccountingDossier {
  const { input, preview } = params;
  const generatedAt = new Date().toISOString();
  const dateStr = generatedAt.slice(0, 10);

  if (input.jurisdiction === "US") {
    const isCorp = input.regime === "C_CORP";
    const irsForm = isCorp
      ? "IRS Form 1120 (Corporate Business Deduction - IRC § 162)"
      : "IRS Schedule C / Form 1065 (Pass-Through Business Deduction - IRC § 162)";

    const record = {
      txnType: "Expense",
      txnDate: dateStr,
      vendorName: input.vendorName,
      description: input.description,
      accountCategory: preview.category,
      irsForm,
      deductible: preview.deductible,
      amountUsd: round2(input.amountUsd),
      incomeTaxShieldUsd: round2(
        preview.taxSavingsBreakdown.incomeTaxShieldUsd
      ),
      taxSavedUsd: round2(preview.taxSavedUsd),
      fiscalDocumentId: input.fiscalDocumentId ?? null,
    };

    const csvExport = buildCsv(
      [
        "Date",
        "Transaction Type",
        "Vendor",
        "Category",
        "Description",
        "Amount USD",
        "Deductible",
        "Tax Shield USD",
        "Document ID",
      ],
      [
        [
          dateStr,
          "Expense",
          input.vendorName,
          preview.category,
          input.description,
          round2(input.amountUsd).toFixed(2),
          preview.deductible ? "YES" : "NO",
          round2(preview.taxSavedUsd).toFixed(2),
          input.fiscalDocumentId ?? "",
        ],
      ]
    );

    return {
      format: "QUICKBOOKS_EXPENSE",
      generatedAt,
      summary: {
        planId: preview.planId,
        jurisdiction: input.jurisdiction,
        regime: input.regime,
        irsForm,
        vendorName: input.vendorName,
        category: preview.category,
        deductible: preview.deductible,
        amountUsd: round2(input.amountUsd),
        taxSavingsBreakdown: preview.taxSavingsBreakdown,
        taxSavedUsd: round2(preview.taxSavedUsd),
        complianceChecklist: preview.complianceChecklist,
      },
      records: [record],
      csvExport,
      disclaimer: TAXRAIL_ACCOUNTING_DISCLAIMER,
    };
  }

  const usdBrlRate = input.usdBrlRate ?? DEFAULT_PTAX_USD_BRL;
  const amountUsd = round2(input.amountUsd);
  const amountBrl = round2(amountUsd * usdBrlRate);
  const incomeTaxShieldUsd = round2(
    preview.taxSavingsBreakdown.incomeTaxShieldUsd
  );
  const pisCofinsCreditUsd = round2(
    preview.taxSavingsBreakdown.pisCofinsCreditUsd
  );
  const ibsCbsReadinessCreditUsd = round2(
    preview.taxSavingsBreakdown.ibsCbsReadinessCreditUsd
  );
  const iofAndSpreadSavingsUsd = round2(
    preview.taxSavingsBreakdown.iofAndSpreadSavingsUsd
  );

  const records: Array<Record<string, unknown>> = [
    {
      erpModule: "OMIE_CONTAS_A_PAGAR_SPED_ECD",
      taxBasis: "IRPJ_CSLL_34_PCT",
      vendorName: input.vendorName,
      description: input.description,
      category: preview.category,
      deductible: preview.deductible,
      fiscalDocumentId: input.fiscalDocumentId ?? null,
      amountUsd,
      amountBrl,
      creditRatePct: 34.0,
      taxShieldUsd: incomeTaxShieldUsd,
      taxShieldBrl: round2(incomeTaxShieldUsd * usdBrlRate),
    },
    {
      erpModule: "SPED_EFD_CONTRIBUICOES",
      taxBasis: "PIS_COFINS_NAO_CUMULATIVO_9_25_PCT",
      vendorName: input.vendorName,
      category: preview.category,
      creditRatePct: 9.25,
      pisRatePct: 1.65,
      cofinsRatePct: 7.6,
      creditUsd: pisCofinsCreditUsd,
      creditBrl: round2(pisCofinsCreditUsd * usdBrlRate),
    },
    {
      erpModule: "IBS_CBS_REFORMA_TRIBUTARIA_TAG",
      taxBasis: "IBS_CBS_READINESS_EC_132_2023",
      vendorName: input.vendorName,
      category: preview.category,
      readinessTag: "IBS_CBS_NAO_CUMULATIVO_PENDENTE_TRANSICAO",
      creditUsd: ibsCbsReadinessCreditUsd,
      creditBrl: round2(ibsCbsReadinessCreditUsd * usdBrlRate),
    },
  ];

  if (iofAndSpreadSavingsUsd > 0) {
    records.push({
      erpModule: "TESOURARIA_CAMBIO_IOF",
      taxBasis: "IOF_E_SPREAD_CAMBIAL_ECONOMIA",
      vendorName: input.vendorName,
      savingsUsd: iofAndSpreadSavingsUsd,
      savingsBrl: round2(iofAndSpreadSavingsUsd * usdBrlRate),
    });
  }

  return {
    format: "BR_LUCRO_REAL_OMIE_SPED",
    generatedAt,
    summary: {
      planId: preview.planId,
      jurisdiction: input.jurisdiction,
      regime: input.regime,
      erpCompatibility: ["OMIE", "SPED_ECD_ECF", "EFD_CONTRIBUICOES"],
      vendorName: input.vendorName,
      category: preview.category,
      deductible: preview.deductible,
      usdBrlRate,
      amountUsd,
      amountBrl,
      irpjCsllRatePct: 34,
      pisCofinsRatePct: 9.25,
      ibsCbsReadiness: {
        enabled: true,
        legalBasis: "EC 132/2023 & LC 214/2025",
        readinessCreditUsd: ibsCbsReadinessCreditUsd,
        readinessCreditBrl: round2(ibsCbsReadinessCreditUsd * usdBrlRate),
      },
      taxSavingsBreakdown: preview.taxSavingsBreakdown,
      taxSavedUsd: round2(preview.taxSavedUsd),
      taxSavedBrl: round2(preview.taxSavedUsd * usdBrlRate),
      complianceChecklist: preview.complianceChecklist,
    },
    records,
    disclaimer: TAXRAIL_ACCOUNTING_DISCLAIMER,
  };
}
